# -- domain: -pi/2 <= x <= pi/2 (trig.py:180-183) -----------------
method(atom_domain, Tan) <- function(x) {
  arg <- .args(x)[[1L]]
  list(-pi / 2 <= arg, arg <= pi / 2)
}

