# -- .grad: d/dx tan(x) = 1/cos(x)^2 (trig.py:185-191) ------------
method(.grad, Tan) <- function(x, values, ...) {
  rows <- as.integer(prod(.arg_shape(x)))
  cols <- as.integer(prod(.shape(x)))
  list(.elemwise_grad_to_diag(1 / cos(values[[1L]])^2, rows, cols))
}
